(() => {
'use strict';
const canvas=document.querySelector('#world'),ctx=canvas.getContext('2d'),mapCanvas=document.querySelector('#mapCanvas'),mctx=mapCanvas.getContext('2d');
const ui={};['regionName','clock','level','healthBar','healthText','xpBar','petIcon','petName','petState','bond','questTitle','questObjective','jambas','jimbies','interactHint','toast','overlay','panelBody','dialogue','speakerName','speakerRole','dialogueText','levelFlash','skillCd','ultCd'].forEach(id=>ui[id]=document.getElementById(id));
const W=2800,H=1800,TAU=Math.PI*2,clamp=(n,a,b)=>Math.max(a,Math.min(b,n)),rand=(a,b)=>a+Math.random()*(b-a),dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
let save;try{save=JSON.parse(localStorage.getItem('jimjack-save')||'null')}catch{save=null}
const state={x:save?.x??330,y:save?.y??650,hp:save?.hp??100,maxHp:100,level:save?.level??1,xp:save?.xp??0,jambas:save?.jambas??120,jimbies:save?.jimbies??2,inventory:save?.inventory??{"Wayfarer's coat":1,"Small tonic":2,"Echo shard":0},quests:save?.quests??{main:0,side:[],done:[]},petUpgraded:save?.petUpgraded??false,bond:save?.bond??0,kills:save?.kills??0,shards:save?.shards??0,runes:save?.runes??0,records:save?.records??0,gameStarted:false,dialogue:null,dialogueQueue:[],panel:null,camX:0,camY:0,attackCd:0,skillCd:0,ultCd:0,invuln:0,attackAnim:0,time:0,day:0,toastTimer:0,joystick:{x:0,y:0},keys:{},lastSave:0,sideDone:save?.sideDone??[],interacted:null};
const player={speed:210,radius:14,faceX:1,faceY:0};
const regions=[{name:'Mosslight Wilds',x:0,color:'#6e9a73',accent:'#a9d695'},{name:'Whisperwood',x:900,color:'#416f62',accent:'#a4c99c'},{name:'The Sunken Crown',x:1750,color:'#738b88',accent:'#e0d399'}];
const mainQuests=[
 {title:'A Signal in the Static',desc:'Find the source of the blue light.',goal:'Reach the fallen signal beacon',kind:'interact',target:'beacon',reward:75},
 {title:'Fragments of Elsewhere',desc:'The beacon scattered pieces of your old world.',goal:'Gather 3 echo fragments',kind:'shards',count:3,reward:100},
 {title:'A Name for the Lost',desc:'Mira knows the paths and the stories behind them.',goal:'Ask Mira about the way home',kind:'interact',target:'mira',reward:120},
 {title:'The Hush Between Trees',desc:'Something in the woods is feeding on the signal.',goal:'Defeat 4 static wraiths',kind:'kills',count:4,reward:150},
 {title:'The Heartroot Crystal',desc:'A heartbeat beneath the oldest hill answers Pip.',goal:'Find the crystal in Gloamroot Hollow',kind:'interact',target:'crystal',reward:220},
 {title:'A Map with No Edge',desc:'The old observatory may explain why this realm knows you.',goal:'Recover 3 observatory records',kind:'records',count:3,reward:160},
 {title:'The Three Quiet Bells',desc:'Wake the ancient waystones in the drowned crown.',goal:'Activate 3 rune bells',kind:'runes',count:3,reward:200},
 {title:'Keeper of the Briar Gate',desc:'The gate will not open while its keeper draws breath.',goal:'Defeat the Briar Keeper',kind:'boss',target:'keeper',reward:250},
 {title:'A Door Made of Stars',desc:'The last signal waits beyond the crown.',goal:'Reach the homeward aperture',kind:'interact',target:'aperture',reward:300},
 {title:'The Unwritten',desc:'The world has one final question for you.',goal:'Face the thing writing your story',kind:'boss',target:'final',reward:500}
];
const sideQuests=[{id:'lost-satchel',title:'The Missing Field Notes',giver:'Mira',desc:'A field researcher lost her notes near the old stone arch.',goal:'Find the lost field notes beneath the stone arch.',reward:90},{id:'lanterns',title:'Lanterns for the Long Night',giver:'Toma',desc:'Help the village keeper light three memory lanterns.',goal:'Light 3 memory lanterns around Brindle.',reward:75},{id:'mushrooms',title:'A Taste of Home',giver:'Seli',desc:'Collect 4 mooncap mushrooms for the village cook.',goal:'Gather 4 mooncap mushrooms.',reward:65}];
const quest=()=>mainQuests[Math.min(state.quests.main,mainQuests.length-1)];
const npcs=[{id:'mira',name:'Mira Venn',role:'Wayfinder · Brindle village',x:610,y:790,color:'#da9d82',icon:'✧',lines:['You came from the blue fracture, didn’t you? It sang your name before you fell.','The road home? There are old observatory records, past the drowned crown. But the road is listening.','I lost my field notes by the stone arch. Bring them back and I’ll share what I found.']},{id:'toma',name:'Toma Reed',role:'Keeper of the lanterns',x:735,y:740,color:'#d9c177',icon:'♧',lines:['Every lantern holds a memory someone was afraid to lose. Strange, isn’t it?','Could you relight the three lanterns? The wind has been whispering in their flames.']},{id:'seli',name:'Seli',role:'Village cook & trader',x:505,y:850,color:'#9ec6a6',icon:'❀',lines:['The mooncaps are blooming early. The forest must be dreaming again.','Bring me four mooncaps and I’ll pack you a proper trail meal.']},{id:'orin',name:'Orin of the Bell',role:'A quiet old guardian',x:2010,y:750,color:'#b3a5db',icon:'◉',lines:['The bells do not ring for the living. They ring for choices.','You are not the first to ask the door for home. You may be the first to hear its answer.']}];
const poi=[{id:'beacon',name:'Fallen signal beacon',x:650,y:535,type:'beacon',color:'#7adcf5',symbol:'✧'},{id:'crystal',name:'Heartroot crystal',x:1480,y:410,type:'crystal',color:'#9af4c9',symbol:'❖'},{id:'arch',name:'Old stone arch',x:1040,y:1035,type:'arch',color:'#d6c38c',symbol:'⌂'},{id:'aperture',name:'Homeward aperture',x:2430,y:500,type:'aperture',color:'#b8a7ff',symbol:'◉'},{id:'keeper',name:'Briar Keeper',x:2140,y:990,type:'boss',color:'#e58876',symbol:'♜'},{id:'final',name:'The Unwritten',x:2520,y:1240,type:'final',color:'#ba9bf5',symbol:'✦'}];
const pickups=[];for(let i=0;i<18;i++)pickups.push({id:'shard'+i,type:'shard',x:rand(420,1810),y:rand(280,1420),got:false});for(let i=0;i<9;i++)pickups.push({id:'moon'+i,type:'mooncap',x:rand(250,1050),y:rand(250,1300),got:false});
const chests=[{x:395,y:390,open:false},{x:1195,y:680,open:false},{x:1870,y:510,open:false},{x:2280,y:1390,open:false}];
const bells=[{x:1920,y:520,on:false},{x:2210,y:760,on:false},{x:2350,y:1150,on:false}];
const lanterns=[{x:520,y:730,on:false},{x:770,y:825,on:false},{x:640,y:920,on:false}];
const records=[{x:1170,y:535,got:false},{x:1370,y:1070,got:false},{x:1790,y:850,got:false}];
const enemies=[];function spawnEnemy(x,y,type='wisp'){enemies.push({x,y,type,hp:type==='keeper'?135:type==='unwritten'?210:38,maxHp:type==='keeper'?135:type==='unwritten'?210:38,r:type==='keeper'?26:type==='unwritten'?33:13,alive:true,hit:0,attack:rand(.4,2),phase:rand(0,8),seed:Math.random()})}
for(let i=0;i<18;i++)spawnEnemy(rand(820,1850),rand(280,1480),i%5===0?'moth':'wisp');
const decorations=[];let seed=4912;function random(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296}for(let i=0;i<270;i++){let x=random()*W,y=random()*H;decorations.push({x,y,type:random()<.68?'tree':random()<.5?'rock':'flower',size:10+random()*26,variant:random()})}
const buildings=[{x:490,y:700,w:90,h:65,color:'#d6b98c'},{x:670,y:660,w:82,h:66,color:'#b6c5a1'},{x:540,y:885,w:74,h:55,color:'#c58f80'},{x:744,y:900,w:95,h:62,color:'#d7c58d'}];
function saveGame(){try{const data={x:state.x,y:state.y,hp:state.hp,level:state.level,xp:state.xp,jambas:state.jambas,jimbies:state.jimbies,inventory:state.inventory,quests:state.quests,petUpgraded:state.petUpgraded,bond:state.bond,kills:state.kills,shards:state.shards,runes:state.runes,records:state.records,sideDone:state.sideDone};localStorage.setItem('jimjack-save',JSON.stringify(data))}catch{}}

input.newString:
function saveGame(){try{const data={x:state.x,y:state.y,hp:state.hp,level:state.level,xp:state.xp,jambas:state.jambas,jimbies:state.jimbies,inventory:state.inventory,quests:state.quests,petUpgraded:state.petUpgraded,bond:state.bond,kills:state.kills,shards:state.shards,runes:state.runes,records:state.records,sideDone:state.sideDone};localStorage.setItem('jimjack-save',JSON.stringify(data))}catch{}}
function toast(msg){ui.toast.textContent=msg;ui.toast.classList.add('show');state.toastTimer=2.5}
function addXP(n){state.xp+=n;while(state.xp>=state.level*100){state.xp-=state.level*100;state.level++;state.maxHp+=12;state.hp=Math.min(state.maxHp,state.hp+35);document.querySelector('#levelFlash').textContent=`LEVEL ${state.level}  ·  VITALITY RESTORED`;ui.levelFlash.classList.remove('hidden');setTimeout(()=>ui.levelFlash.classList.add('hidden'),1800);toast(`Level ${state.level}! Your journey deepens.`)}}
function reward(j){state.jambas+=j.reward;addXP(55+state.quests.main*12);state.bond+=1;state.quests.done.push(j.title);state.quests.main++;toast(`Tale complete · +${j.reward} Jambas · +55 XP`);if(state.quests.main>=mainQuests.length){showDialogue('The Unwritten','A voice beyond the page','The way home opens. It is not a door but a choice. You can return to the life you remember—or stay in the world that learned your name.','ending')}updateHud();saveGame()}
function event(kind,target){const q=quest();if(q.kind!==kind||q.target&&q.target!==target)return false;if(kind==='interact'){if(target==='crystal'&&!state.petUpgraded){state.petUpgraded=true;state.bond+=8;state.hp=state.maxHp;showDialogue('Pip','A new voice in the green','The crystal unfolds like a small sun. Pip’s soft green glow becomes a mane of living leaves; a great green wolf lowers its head, and your old companion is still there—brighter, stronger, home.','evolution');}else if(target==='final'){showDialogue('The Unwritten','The last page','I began as a game someone forgot to finish. You gave me a world by believing it was real. Tell me, Wanderer—will you go home, or will you stay and write what comes next?','ending')}else{showDialogue(target==='mira'?'Mira Venn':poi.find(p=>p.id===target)?.name||'A voice',target==='beacon'?'A faint signal': 'The path ahead',target==='beacon'?'The beacon pulses in time with your heartbeat. A voice buried in the static whispers: “You’re not supposed to be here.”':'The old stones vibrate beneath your hand. Somewhere far away, a bell answers.','quest')}reward(q);return true}if(kind==='boss'){reward(q);return true}return false}
function objectiveText(){const q=quest();let n=0;if(q.kind==='shards')n=state.shards;else if(q.kind==='kills')n=state.kills;else if(q.kind==='records')n=state.records;else if(q.kind==='runes')n=state.runes;return q.count?`${q.goal} · ${Math.min(n,q.count)}/${q.count}`:q.goal}
function updateHud(){const q=quest();ui.questTitle.textContent=q.title;ui.questObjective.textContent=objectiveText();ui.level.textContent=`LV ${state.level}`;ui.healthBar.style.width=`${100*state.hp/state.maxHp}%`;ui.healthText.textContent=`${Math.ceil(state.hp)} / ${state.maxHp}`;ui.xpBar.style.width=`${100*state.xp/(state.level*100)}%`;ui.jambas.textContent=state.jambas;ui.jimbies.textContent=state.jimbies;ui.bond.textContent=state.bond;ui.petName.textContent=state.petUpgraded?'Verdant':'Pip';ui.petIcon.textContent=state.petUpgraded?'🐺':'◈';ui.petState.textContent=state.petUpgraded?'Heartroot guardian':'Curious companion';if(!state.petUpgraded)ui.petIcon.style.color='#9be0ad'}
function showDialogue(name,role,text,kind='talk'){state.dialogue={name,role,text,kind};ui.speakerName.textContent=name;ui.speakerRole.textContent=role;ui.dialogueText.textContent=text;ui.dialogue.classList.remove('hidden')}
function nextDialogue(){if(state.dialogue?.kind==='evolution'){showDialogue('Verdant','Heartroot wolf','I remember the little steps. I remember the dark. I remember you. Let’s find the ending together.','talk');return}if(state.dialogue?.kind==='ending'){ui.dialogue.classList.add('hidden');showPanel('ending');return}ui.dialogue.classList.add('hidden');state.dialogue=null}
function interact(){if(state.dialogue){nextDialogue();return}let all=[...npcs,...poi,...chests.filter(c=>!c.open).map((c,i)=>({...c,id:'chest'+i,name:'Wayfarer cache',type:'chest'})),...pickups.filter(p=>!p.got).map(p=>({...p,name:p.type==='shard'?'Echo fragment':'Mooncap mushroom'})),...bells.filter(b=>!b.on).map((b,i)=>({...b,id:'bell'+i,name:'Quiet bell',type:'bell'})),...lanterns.filter(l=>!l.on).map((l,i)=>({...l,id:'lantern'+i,name:'Memory lantern',type:'lantern'})),...records.filter(r=>!r.got).map((r,i)=>({...r,id:'record'+i,name:'Observatory record',type:'record'}))];all=all.filter(o=>dist(state,o)<74).sort((a,b)=>dist(state,a)-dist(state,b));const o=all[0];if(!o){toast('Nothing nearby to interact with.');return}if(o.id==='beacon'){if(state.quests.main===0)event('interact','beacon');else showDialogue('Signal beacon','A familiar static','The blue light hums softly. The signal has already given you its first clue.');return}if(o.id==='crystal'){if(state.quests.main===4)event('interact','crystal');else toast('A sealed green light sleeps beneath the hill.');return}if(o.id==='aperture'){if(state.quests.main===8)event('interact','aperture');else toast('The star aperture is dormant. The three bells may wake it.');return}if(o.id==='keeper'||o.id==='final'){toast('A dangerous presence. Strike to begin the encounter.');return}if(o.type==='chest'){o.open=true;const coins=35+Math.floor(Math.random()*35);state.jambas+=coins;state.jimbies+=Math.random()<.25?1:0;state.inventory['Small tonic']=(state.inventory['Small tonic']||0)+1;addXP(25);toast(`Cache opened · +${coins} Jambas · Small tonic`);updateHud();saveGame();return}if(o.type==='shard'){o.got=true;state.shards++;state.jambas+=8;state.inventory['Echo shard']=(state.inventory['Echo shard']||0)+1;toast('Echo fragment gathered · +8 Jambas');if(state.quests.main===1&&state.shards>=3)reward(quest());updateHud();saveGame();return}if(o.type==='mooncap'){o.got=true;state.inventory['Mooncap mushroom']=(state.inventory['Mooncap mushroom']||0)+1;toast('Mooncap mushroom gathered');updateHud();return}if(o.type==='record'){o.got=true;state.records++;state.inventory['Observatory record']=(state.inventory['Observatory record']||0)+1;toast('Observatory record recovered');if(state.quests.main===5&&state.records>=3)reward(quest());updateHud();saveGame();return}if(o.type==='bell'){o.on=true;state.runes++;state.jambas+=15;toast(`Quiet bell awakened · ${state.runes}/3`);if(state.quests.main===6&&state.runes>=3)reward(quest());updateHud();return}if(o.type==='lantern'){o.on=true;state.quests.side.find(s=>s.id==='lanterns')?.progress++;toast('A memory lantern glows again');checkSide('lanterns');return}if(o.id==='arch'){const sq=state.quests.side.find(s=>s.id==='lost-satchel');if(sq){sq.progress=1;checkSide(sq.id)}else toast('A weathered arch; someone has scratched a tiny map into its stone.');return}if(npcs.some(n=>n.id===o.id)){npcTalk(o);return}toast('The wind moves through the grass.')}
function npcTalk(n){let text=n.lines[0];if(n.id==='mira'){if(state.quests.main===2){text=n.lines[1];event('interact','mira')}else if(!state.sideDone.includes('lost-satchel')&&!state.quests.side.some(s=>s.id==='lost-satchel')){text=n.lines[2];state.quests.side.push({...sideQuests[0],progress:0});toast('Side tale added: The Missing Field Notes')}else if(state.quests.side.some(s=>s.id==='lost-satchel'))text='You found the notes! The margin says the observatory is older than the world itself.'}if(n.id==='toma'&&!state.sideDone.includes('lanterns')&&!state.quests.side.some(s=>s.id==='lanterns')){state.quests.side.push({...sideQuests[1],progress:0});text=n.lines[1];toast('Side tale added: Lanterns for the Long Night')}if(n.id==='seli'&&!state.sideDone.includes('mushrooms')&&!state.quests.side.some(s=>s.id==='mushrooms')){state.quests.side.push({...sideQuests[2],progress:0});text=n.lines[1];toast('Side tale added: A Taste of Home')}if(n.id==='seli'&&state.quests.side.some(s=>s.id==='mushrooms'))text='These mooncaps smell like rain on warm stone. You brought just enough.';if(n.id==='orin'&&state.quests.main>=6)text=n.lines[1];showDialogue(n.name,n.role,text);if(n.id==='seli')checkSide('mushrooms')}
function checkSide(id){const s=state.quests.side.find(s=>s.id===id);if(!s)return;let done=id==='lost-satchel'?s.progress>=1:id==='lanterns'?lanterns.filter(l=>l.on).length>=3:id==='mushrooms'?(state.inventory['Mooncap mushroom']||0)>=4:false;if(done){state.jambas+=s.reward;state.jimbies+=id==='lost-satchel'?1:0;state.sideDone.push(id);state.quests.side=state.quests.side.filter(q=>q.id!==id);toast(`Side tale complete · +${s.reward} Jambas${id==='lost-satchel'?' · +1 Jimbies':''}`);addXP(45);saveGame()}}

