function checkSide(id){const s=state.quests.side.find(s=>s.id===id);if(!s)return;let done=id==='lost-satchel'?s.progress>=1:id==='lanterns'?lanterns.filter(l=>l.on).length>=3:id==='mushrooms'?(state.inventory['Mooncap mushroom']||0)>=4:false;if(done){state.jambas+=s.reward;state.jimbies+=id==='lost-satchel'?1:0;if(id==='mushrooms')state.inventory['Mooncap mushroom']-=4;state.sideDone.push(id);state.quests.side=state.quests.side.filter(q=>q.id!==id);toast(`Side tale complete · +${s.reward} Jambas${id==='lost-satchel'?' · +1 Jimbies':''}`);addXP(45);saveGame()}}
function showPanel(which){state.panel=which;ui.overlay.classList.remove('hidden');renderPanel(which)}
function closePanel(){ui.overlay.classList.add('hidden');state.panel=null}
function renderPanel(which,tab=''){const body=ui.panelBody;let html='';if(which==='quests'){html=`<h2>Journey log</h2><p class="lead">Tales are threads. Follow them and the realm will unfold.</p><div class="tab-row"><button class="active">Main tales</button><button>Side tales · ${state.quests.side.length}</button></div><div class="list-row"><span class="list-icon">✦</span><div><small>CHAPTER ${Math.min(state.quests.main+1,10)} OF 10</small><br><b>${quest().title}</b><p>${quest().desc}<br><strong>${objectiveText()}</strong></p></div></div>${state.quests.side.map(s=>`<div class="list-row"><span class="list-icon">◇</span><div><small>SIDE TALE</small><br><b>${s.title}</b><p>${s.desc}<br>${s.goal}</p></div></div>`).join('')}<div class="list-row"><span class="list-icon">✓</span><div><small>COMPLETED</small><br><b>${state.quests.done.length} main tales · ${state.sideDone.length} side tales</b><p>Keep exploring. The world holds more than the road home.</p></div></div>`}
else if(which==='inventory'){const items=Object.entries(state.inventory).filter(([,n])=>n>0);html=`<h2>Wayfarer's satchel</h2><p class="lead">Your collected keepsakes, supplies, and tools.</p><div class="inventory-grid">${items.map(([name,count])=>`<div class="item"><span>${name.includes('shard')?'✧':name.includes('tonic')?'⚗':name.includes('coat')?'◈':name.includes('mushroom')?'❀':'▤'}</span><b>${name}</b><small>Quantity · ${count}</small>${name==='Small tonic'?'<button onclick="window.useTonic()">Use · restore 45 HP</button>':''}</div>`).join('')}</div><div class="list-row"><span class="list-icon">⚔</span><div><b>Equipped · Wayfarer's coat</b><p>Worn fabric, stitched with a symbol you almost recognize.</p></div></div>`}
else if(which==='map'){html=`<h2>Atlas of the Unwritten</h2><p class="lead">The realm grows clearer as you travel. Three regions, one impossible horizon.</p><div class="large-map"><canvas id="bigMap" width="680" height="320"></canvas></div><div class="region-list">${regions.map((r,i)=>`<div class="list-row"><span class="list-icon">${i===0?'❋':i===1?'♧':'◈'}</span><div><b>${r.name}</b><p>${i===0?'Meadow paths · Brindle village · Signal beacon':i===1?'Whispering woods · Gloamroot Hollow · Old observatory':'Drowned ruins · Quiet bells · Star aperture'}</p></div><small>${state.x>=r.x?'DISCOVERED':'UNEXPLORED'}</small></div>`).join('')}</div>`}
else if(which==='shop'){html=`<h2>Seli's Traveling Counter</h2><p class="lead">Small comforts for a long road. Jambas: ✧ ${state.jambas} · Jimbies: ❖ ${state.jimbies}</p><div class="list-row"><span class="list-icon">⚗</span><div><b>Small tonic</b><p>Restore 45 health. A little warmth in a glass bottle.</p><small>35 JAMBAS</small></div><button onclick="window.buyItem('Small tonic',35)">Buy</button></div><div class="list-row"><span class="list-icon">✦</span><div><b>Star-kissed salve</b><p>Restore all health and add a little max vitality.</p><small>1 JIMBIES</small></div><button onclick="window.buyRare()">Buy</button></div><div class="list-row"><span class="list-icon">⚔</span><div><b>Honed wanderer's blade</b><p>Sharpen your edge. Strike damage increased permanently.</p><small>120 JAMBAS</small></div><button onclick="window.buyBlade()">Buy</button></div>`}
else if(which==='settings'){html=`<h2>Field settings</h2><p class="lead">The realm keeps a gentle pace. Your progress saves automatically.</p><div class="list-row"><span class="list-icon">⌨</span><div><b>Controls</b><p>Move WASD / arrows · Dash Shift · Interact F · Strike Space / click · Arc pulse E · Starfall Q<br>On touchscreens use the left joystick and action buttons.</p></div></div><div class="list-row"><span class="list-icon">◌</span><div><b>Journey save</b><p>${state.quests.done.length} tales completed · Level ${state.level} · ${state.petUpgraded?'Heartroot bond awakened':'Pip is still growing'}</p></div><button onclick="window.resetGame()">New journey</button></div>`}
else if(which==='ending'){html=`<div class="ending"><div class="title-mark">✧</div><p class="eyebrow">THE LAST PAGE IS YOURS</p><h2>Where the story goes</h2><p class="lead">The aperture holds two truths: the life you left behind, and the people who will remember you here.</p><button class="choice" onclick="window.chooseEnding('home')">Return home · “I will remember.”</button><button class="choice" onclick="window.chooseEnding('stay')">Stay · “Let’s write the next page.”</button></div>`}
body.innerHTML=html;if(which==='map')drawBigMap(document.getElementById('bigMap'))}
window.useTonic=()=>{if((state.inventory['Small tonic']||0)<1)return toast('No tonics left.');if(state.hp>=state.maxHp)return toast('You are already at full health.');state.inventory['Small tonic']--;state.hp=Math.min(state.maxHp,state.hp+45);toast('Small tonic used · health restored');updateHud();renderPanel('inventory')};window.buyItem=(name,cost)=>{if(state.jambas<cost)return toast('Not enough Jambas.');state.jambas-=cost;state.inventory[name]=(state.inventory[name]||0)+1;updateHud();renderPanel('shop');toast(`${name} purchased`)};window.buyRare=()=>{if(state.jimbies<1)return toast('Not enough Jimbies.');state.jimbies--;state.hp=state.maxHp;state.maxHp+=8;updateHud();renderPanel('shop');toast('Star-kissed salve · vitality increased')};window.buyBlade=()=>{if(state.jambas<120)return toast('Not enough Jambas.');if(state.inventory['Honed blade'])return toast('Your blade is already honed.');state.jambas-=120;state.inventory['Honed blade']=1;updateHud();renderPanel('shop');toast('Honed blade equipped · strikes hit harder')};window.resetGame=()=>{if(confirm('Start a new journey? This erases the current local save.')){localStorage.removeItem('jimjack-save');location.reload()}};window.chooseEnding=(choice)=>{state.ending=choice;saveGame();closePanel();showDialogue('The Unwritten','A softer kind of magic',choice==='home'?'The world opens around you. On your desk, the game is still running—and a small green leaf rests beside the keyboard. You carry the realm with you.':'You stay. At dawn, Mira brings a blank map. Pip curls beside your boots. The first line is yours to write.','talk');document.querySelector('#dialogueNext').textContent='The End · Continue wandering ↗'};
function drawBigMap(c){if(!c)return;const x=c.getContext('2d'),w=c.width,h=c.height;x.fillStyle='#203c3b';x.fillRect(0,0,w,h);for(let i=0;i<3;i++){x.fillStyle=['#7b9b70','#426a5a','#6a7f82'][i];x.fillRect(i*w/3,0,w/3,h)}x.fillStyle='#bea77a';x.globalAlpha=.6;x.beginPath();x.moveTo(40,h*.65);x.bezierCurveTo(w*.25,h*.5,w*.32,h*.8,w*.46,h*.56);x.bezierCurveTo(w*.62,h*.34,w*.65,h*.68,w*.92,h*.35);x.lineWidth=14;x.strokeStyle='#cbb88b';x.stroke();x.globalAlpha=1;for(const p of [...npcs,...poi]){const xx=p.x/W*w,yy=p.y/H*h;x.fillStyle=p.color||'#e4cd8a';x.beginPath();x.arc(xx,yy,p.id==='beacon'?5:3,0,TAU);x.fill()}x.fillStyle='#fff';x.beginPath();x.arc(state.x/W*w,state.y/H*h,5,0,TAU);x.fill();x.strokeStyle='#fff9';x.lineWidth=2;x.stroke()}

