function drawBigMap(c){if(!c)return;const x=c.getContext('2d'),w=c.width,h=c.height;x.fillStyle='#203c3b';x.fillRect(0,0,w,h);for(let i=0;i<3;i++){x.fillStyle=['#7b9b70','#426a5a','#6a7f82'][i];x.fillRect(i*w/3,0,w/3,h)}x.fillStyle='#bea77a';x.globalAlpha=.6;x.beginPath();x.moveTo(40,h*.65);x.bezierCurveTo(w*.25,h*.5,w*.32,h*.8,w*.46,h*.56);x.bezierCurveTo(w*.62,h*.34,w*.65,h*.68,w*.92,h*.35);x.lineWidth=14;x.strokeStyle='#cbb88b';x.stroke();x.globalAlpha=1;for(const p of [...npcs,...poi]){const xx=p.x/W*w,yy=p.y/H*h;x.fillStyle=p.color||'#e4cd8a';x.beginPath();x.arc(xx,yy,p.id==='beacon'?5:3,0,TAU);x.fill()}x.fillStyle='#fff';x.beginPath();x.arc(state.x/W*w,state.y/H*h,5,0,TAU);x.fill();x.strokeStyle='#fff9';x.lineWidth=2;x.stroke()}
function resize(){const d=Math.min(devicePixelRatio||1,2),r=canvas.getBoundingClientRect();canvas.width=Math.floor(r.width*d);canvas.height=Math.floor(r.height*d);ctx.setTransform(d,0,0,d,0,0)}window.addEventListener('resize',resize);resize();
function drawWorld(){const w=canvas.clientWidth,h=canvas.clientHeight;state.camX=clamp(state.x-w/2,0,W-w);state.camY=clamp(state.y-h/2,0,H-h);ctx.clearRect(0,0,w,h);const sky=ctx.createLinearGradient(0,0,0,h);sky.addColorStop(0,'#a4bca7');sky.addColorStop(.5,'#91aa83');sky.addColorStop(1,'#687f68');ctx.fillStyle=sky;ctx.fillRect(0,0,w,h);ctx.save();ctx.translate(-state.camX,-state.camY);
// Regional ground, softly blended at each threshold.
ctx.fillStyle='#77966e';ctx.fillRect(0,0,930,H);ctx.fillStyle='#496e5e';ctx.fillRect(940,0,840,H);ctx.fillStyle='#738688';ctx.fillRect(1790,0,W-1790,H);for(let i=0;i<8;i++){const x=900+i*18;ctx.fillStyle=`rgba(53,94,71,${.025+i*.004})`;ctx.fillRect(x,0,20,H)}
// distant ridge silhouettes
for(let layer=0;layer<3;layer++){ctx.beginPath();ctx.moveTo(state.camX-100,H+state.camY);for(let x=state.camX-100;x<state.camX+w+120;x+=40){const y=state.camY+130+layer*70+Math.sin(x*.008+layer*2)*28+Math.sin(x*.019)*12;ctx.lineTo(x,y)}ctx.lineTo(state.camX+w+120,state.camY+H);ctx.closePath();ctx.fillStyle=['#637b72','#557264','#3c5a51'][layer];ctx.globalAlpha=.16;ctx.fill()}ctx.globalAlpha=1;
// wandering trail
ctx.beginPath();ctx.moveTo(245,650);ctx.bezierCurveTo(470,500,700,980,925,720);ctx.bezierCurveTo(1100,510,1180,1210,1430,1050);ctx.bezierCurveTo(1620,920,1710,570,1910,700);ctx.bezierCurveTo(2100,840,2230,450,2520,520);ctx.lineWidth=76;ctx.lineCap='round';ctx.strokeStyle='#b8a47a';ctx.globalAlpha=.55;ctx.stroke();ctx.lineWidth=61;ctx.strokeStyle='#c5b58c';ctx.globalAlpha=.45;ctx.stroke();ctx.globalAlpha=1;
// clearings and lake
const lake=ctx.createRadialGradient(2230,1320,35,2230,1320,260);lake.addColorStop(0,'#64a4a7');lake.addColorStop(.75,'#377b88');lake.addColorStop(1,'#426f76');ctx.fillStyle=lake;ctx.beginPath();ctx.ellipse(2220,1320,235,150,-.2,0,TAU);ctx.fill();ctx.strokeStyle='#b8d2b077';ctx.lineWidth=3;ctx.stroke();for(let i=0;i<13;i++){const x=2080+(i*79)%280,y=1270+(i*47)%110;ctx.strokeStyle='#d5f1cf3a';ctx.beginPath();ctx.ellipse(x,y,15+i%3*8,3,0,0,TAU);ctx.stroke()}
// grass flecks
for(let i=0;i<240;i++){const x=((i*197+73)%W),y=((i*313+23)%H);if(x<state.camX-20||x>state.camX+w+20||y<state.camY-20||y>state.camY+h+20)continue;ctx.strokeStyle=i%3?'#d4dfaa28':'#344e4130';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+3,y-5);ctx.stroke()}
// decorations
for(const d of decorations){if(d.x<state.camX-60||d.x>state.camX+w+60||d.y<state.camY-70||d.y>state.camY+h+70)continue;if(d.type==='tree')drawTree(d);else if(d.type==='rock')drawRock(d);else drawFlower(d)}
// village buildings
for(const b of buildings)drawBuilding(b);
// interactive objects and collectibles
for(const p of poi)drawPoi(p);for(const c of chests)if(!c.open)drawChest(c);for(const p of pickups)if(!p.got)drawPickup(p);for(const b of bells)if(!b.on)drawBell(b);for(const l of lanterns)if(!l.on)drawLantern(l);for(const r of records)if(!r.got)drawRecord(r);
for(const n of npcs)drawCharacter(n.x,n.y,n.color,n.icon,n.name,false);
for(const e of enemies)if(e.alive)drawEnemy(e);
// Companion trails behind, scaled by evolution
const tail={x:state.x-player.faceX*(state.petUpgraded?37:27),y:state.y-player.faceY*(state.petUpgraded?37:27)+5};drawPet(tail.x,tail.y);
drawPlayer();drawParticles();ctx.restore();drawMap();drawLighting(w,h);updateRegion();}
function drawTree(d){const s=d.size,forest=d.x>850;ctx.fillStyle='#1c342c44';ctx.beginPath();ctx.ellipse(d.x+7,d.y+8,s*.8,s*.32,0,0,TAU);ctx.fill();ctx.fillStyle=forest?'#493b2d':'#765542';ctx.fillRect(d.x-s*.12,d.y-s*.1,s*.24,s*.7);const colors=forest?['#234a3f','#2b5845','#3c6b50']:['#477447','#57824c','#668b50'];ctx.fillStyle=colors[Math.floor(d.variant*3)];ctx.beginPath();ctx.arc(d.x,d.y-s*.35,s*.65,0,TAU);ctx.arc(d.x-s*.33,d.y-s*.22,s*.42,0,TAU);ctx.arc(d.x+s*.3,d.y-s*.2,s*.4,0,TAU);ctx.fill();ctx.fillStyle='#d7e3a322';ctx.beginPath();ctx.arc(d.x-s*.2,d.y-s*.53,s*.25,0,TAU);ctx.fill()}
function drawRock(d){ctx.fillStyle='#263a3940';ctx.beginPath();ctx.ellipse(d.x+3,d.y+5,d.size*.8,d.size*.34,0,0,TAU);ctx.fill();ctx.fillStyle=d.x>1750?'#88938b':'#829078';ctx.beginPath();ctx.moveTo(d.x-d.size*.6,d.y);ctx.lineTo(d.x-d.size*.35,d.y-d.size*.65);ctx.lineTo(d.x+d.size*.2,d.y-d.size*.8);ctx.lineTo(d.x+d.size*.65,d.y-d.size*.3);ctx.lineTo(d.x+d.size*.5,d.y+d.size*.15);ctx.closePath();ctx.fill();ctx.strokeStyle='#d7dec143';ctx.stroke()}
function drawFlower(d){ctx.fillStyle=d.variant>.5?'#ecd792':'#dfaaae';ctx.beginPath();for(let i=0;i<5;i++){const a=i*TAU/5;ctx.moveTo(d.x,d.y);ctx.arc(d.x+Math.cos(a)*3,d.y+Math.sin(a)*3,2.4,0,TAU)}ctx.fill();ctx.fillStyle='#e6d785';ctx.beginPath();ctx.arc(d.x,d.y,1.3,0,TAU);ctx.fill()}
function drawBuilding(b){ctx.fillStyle='#28353255';ctx.beginPath();ctx.ellipse(b.x+b.w/2,b.y+b.h*.8,b.w*.7,15,0,0,TAU);ctx.fill();ctx.fillStyle=b.color;ctx.fillRect(b.x,b.y,b.w,b.h);ctx.fillStyle='#694b48';ctx.beginPath();ctx.moveTo(b.x-9,b.y+5);ctx.lineTo(b.x+b.w/2,b.y-34);ctx.lineTo(b.x+b.w+9,b.y+5);ctx.closePath();ctx.fill();ctx.fillStyle='#795b4e';ctx.fillRect(b.x+b.w*.4,b.y+b.h*.45,b.w*.2,b.h*.55);ctx.fillStyle='#f0da9a';ctx.fillRect(b.x+12,b.y+17,12,13);ctx.fillRect(b.x+b.w-25,b.y+17,12,13);ctx.fillStyle='#fff2ba80';ctx.fillRect(b.x+13,b.y+18,2,11)}

