const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({ headless: true, args: ['--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 1365, height: 900 } });
  const errors = [];
  page.on('console', message => { if (message.type() === 'error') errors.push(`console: ${message.text()}`); });
  page.on('pageerror', error => errors.push(`pageerror: ${error.message}`));
  page.on('response', response => { if (response.status() >= 400) errors.push(`HTTP ${response.status()} ${response.url()}`); });

  await page.goto('http://localhost:3002');
  await page.evaluate(() => localStorage.clear());
  await page.reload();
  await page.click('#playBtn');
  const start = await page.evaluate(() => JSON.parse(localStorage.getItem('jimjack-save')));

  // Move east, then north; the beacon is northeast but not on the 45-degree diagonal.
  await page.keyboard.down('d');
  await page.waitForTimeout(1200);
  await page.keyboard.up('d');
  await page.keyboard.down('w');
  await page.waitForTimeout(500);
  await page.keyboard.up('w');
  await page.keyboard.press('f');
  const moved = await page.evaluate(() => JSON.parse(localStorage.getItem('jimjack-save')));
  const dialogue = await page.locator('#dialogueText').textContent();
  await page.keyboard.press('f');

  await page.locator('[data-panel="quests"]').click();
  const questPanel = await page.locator('#panelBody').innerText();
  await page.locator('#closePanel').click();
  await page.setViewportSize({ width: 390, height: 844 });
  const mobile = await page.evaluate(() => ({
    body: document.body.scrollWidth,
    inner: innerWidth,
    controls: getComputedStyle(document.querySelector('.mobile-controls')).display,
    canvas: document.querySelector('#world').getBoundingClientRect().toJSON()
  }));

  console.log(JSON.stringify({
    start: { x: start.x, y: start.y, main: start.quests.main },
    moved: { x: moved.x, y: moved.y, main: moved.quests.main, done: moved.quests.done },
    dialogue,
    questPanel: questPanel.slice(0, 200),
    errors,
    mobile
  }, null, 2));
  await browser.close();
})().catch(error => { console.error(error); process.exit(1); });

