function nextDialogue(){if(state.dialogue?.kind==='evolution'){showDialogue('Verdant','Heartroot wolf','I remember the little steps. I remember the dark. I remember you. Let’s find the ending together.','talk');return}if(state.dialogue?.kind==='ending'){ui.dialogue.classList.add('hidden');showPanel('ending');return}ui.dialogue.classList.add('hidden');state.dialogue=null}
function interact(){if(state.dialogue){nextDialogue();return}let all=[...npcs,...poi,...chests.filter(c=>!c.open).map((c,i)=>(c.id='chest'+i,c.name='Wayfarer cache',c.type='chest',c)),...pickups.filter(p=>!p.got).map(p=>(p.name=p.type==='shard'?'Echo fragment':'Mooncap mushroom',p)),...bells.filter(b=>!b.on).map((b,i)=>(b.id='bell'+i,b.name='Quiet bell',b.type='bell',b)),...lanterns.filter(l=>!l.on).map((l,i)=>(l.id='lantern'+i,l.name='Memory lantern',l.type='lantern',l)),...records.filter(r=>!r.got).map((r,i)=>(r.id='record'+i,r.name='Observatory record',r.type='record',r))];all=all.filter(o=>dist(state,o)<74).sort((a,b)=>dist(state,a)-dist(state,b));const o=all[0];if(!o){toast('Nothing nearby to interact with.');return}if(o.id==='beacon'){if(state.quests.main===0)event('interact','beacon');else showDialogue('Signal beacon','A familiar static','The blue light hums softly. The signal has already given you its first clue.');return}if(o.id==='crystal'){if(state.quests.main===4)event('interact','crystal');else toast('A sealed green light sleeps beneath the hill.');return}if(o.id==='aperture'){if(state.quests.main===8)event('interact','aperture');else toast('The star aperture is dormant. The three bells may wake it.');return}if(o.id==='keeper'||o.id==='final'){toast('A dangerous presence. Strike to begin the encounter.');return}if(o.type==='chest'){o.open=true;const coins=35+Math.floor(Math.random()*35);state.jambas+=coins;state.jimbies+=Math.random()<.25?1:0;state.inventory['Small tonic']=(state.inventory['Small tonic']||0)+1;addXP(25);toast(`Cache opened · +${coins} Jambas · Small tonic`);updateHud();saveGame();return}if(o.type==='shard'){o.got=true;state.shards++;state.jambas+=8;state.inventory['Echo shard']=(state.inventory['Echo shard']||0)+1;toast('Echo fragment gathered · +8 Jambas');if(state.quests.main===1&&state.shards>=3)reward(quest());updateHud();saveGame();return}if(o.type==='mooncap'){o.got=true;state.inventory['Mooncap mushroom']=(state.inventory['Mooncap mushroom']||0)+1;toast('Mooncap mushroom gathered');updateHud();return}if(o.type==='record'){o.got=true;state.records++;state.inventory['Observatory record']=(state.inventory['Observatory record']||0)+1;toast('Observatory record recovered');if(state.quests.main===5&&state.records>=3)reward(quest());updateHud();saveGame();return}if(o.type==='bell'){o.on=true;state.runes++;state.jambas+=15;toast(`Quiet bell awakened · ${state.runes}/3`);if(state.quests.main===6&&state.runes>=3)reward(quest());updateHud();return}if(o.type==='lantern'){o.on=true;const side=state.quests.side.find(s=>s.id==='lanterns');if(side)side.progress=lanterns.filter(l=>l.on).length;toast('A memory lantern glows again');checkSide('lanterns');saveGame();return}if(o.id==='arch'){const sq=state.quests.side.find(s=>s.id==='lost-satchel');if(sq){sq.progress=1;toast('Field notes found · return them to Mira in Brindle.');saveGame()}else toast('A weathered arch; someone has scratched a tiny map into its stone.');return}if(npcs.some(n=>n.id===o.id)){npcTalk(o);return}toast('The wind moves through the grass.')}
function npcTalk(n){let text=n.lines[0];if(n.id==='mira'){if(state.quests.main===2){text=n.lines[1];event('interact','mira')}else if(!state.sideDone.includes('lost-satchel')&&!state.quests.side.some(s=>s.id==='lost-satchel')){text=n.lines[2];state.quests.side.push({...sideQuests[0],progress:0});toast('Side tale added: The Missing Field Notes')}else if(state.quests.side.some(s=>s.id==='lost-satchel')){const side=state.quests.side.find(s=>s.id==='lost-satchel');if(side.progress>=1){side.progress=2;checkSide('lost-satchel');text='You found the notes! The margin says the observatory is older than the world itself.'}else text='The notes are still missing. Look beneath the old stone arch.'}}if(n.id==='toma'&&!state.sideDone.includes('lanterns')&&!state.quests.side.some(s=>s.id==='lanterns')){state.quests.side.push({...sideQuests[1],progress:0});text=n.lines[1];toast('Side tale added: Lanterns for the Long Night')}if(n.id==='seli'&&!state.sideDone.includes('mushrooms')&&!state.quests.side.some(s=>s.id==='mushrooms')){state.quests.side.push({...sideQuests[2],progress:0});text=n.lines[1];toast('Side tale added: A Taste of Home')}if(n.id==='seli'&&state.quests.side.some(s=>s.id==='mushrooms'))text='These mooncaps smell like rain on warm stone. You brought just enough.';if(n.id==='orin'&&state.quests.main>=6)text=n.lines[1];showDialogue(n.name,n.role,text);if(n.id==='seli')checkSide('mushrooms');if(n.id==='toma')checkSide('lanterns');saveGame()}
function checkSide(id){const s=state.quests.side.find(s=>s.id===id);if(!s)return;let done=id==='lost-satchel'?s.progress>=2:id==='lanterns'?lanterns.filter(l=>l.on).length>=3:id==='mushrooms'?(state.inventory['Mooncap mushroom']||0)>=4:false;if(done){state.jambas+=s.reward;state.jimbies+=id==='lost-satchel'?1:0;if(id==='mushrooms')state.inventory['Mooncap mushroom']-=4;state.sideDone.push(id);state.quests.side=state.quests.side.filter(q=>q.id!==id);toast(`Side tale complete · +${s.reward} Jambas${id==='lost-satchel'?' · +1 Jimbies':''}`);addXP(45);saveGame()}}
function showPanel(which){state.panel=which;ui.overlay.classList.remove('hidden');renderPanel(which)}

