const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({ headless: true, args: ['--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 1365, height: 900 } });
  const errors = [];
  page.on('pageerror', e => errors.push(e.message));
  await page.goto('http://localhost:3002');
  await page.evaluate(() => localStorage.clear());
  await page.reload();
  await page.click('#playBtn');
  await page.evaluate(() => {
    localStorage.setItem('jimjack-save', JSON.stringify({ x: 505, y: 850, hp: 60, maxHp: 120, level: 2, xp: 0, jambas: 300, jimbies: 2, inventory: { "Wayfarer's coat": 1, 'Small tonic': 2 }, quests: { main: 0, side: [], done: [] }, petUpgraded: false, bond: 0, kills: 0, shards: 0, runes: 0, records: 0, sideDone: [] }));
  });
  await page.reload();
  await page.click('#playBtn');
  await page.keyboard.press('f');
  await page.click('#shopFromDialogue');
  await page.locator('#panelBody button').nth(0).click();
  const bought = await page.evaluate(() => JSON.parse(localStorage.getItem('jimjack-save')));
  await page.reload();
  const afterPurchaseReload = await page.evaluate(() => JSON.parse(localStorage.getItem('jimjack-save')));
  await page.evaluate(() => window.chooseEnding('home'));
  const endingBeforeReload = await page.evaluate(() => JSON.parse(localStorage.getItem('jimjack-save')).ending);
  await page.reload();
  const afterEndingReload = await page.evaluate(() => JSON.parse(localStorage.getItem('jimjack-save')));
  console.log(JSON.stringify({ purchase: { jambas: bought.jambas, tonics: bought.inventory['Small tonic'] }, purchaseReload: { jambas: afterPurchaseReload.jambas, tonics: afterPurchaseReload.inventory['Small tonic'] }, maxHp: afterPurchaseReload.maxHp, endingBeforeReload, endingAfterReload: afterEndingReload.ending, errors }, null, 2));
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

